-- Frozen initial schema. Future changes require a new numbered migration.
CREATE TABLE "admin_user" ("id" INTEGER NOT NULL PRIMARY KEY, "username" TEXT NOT NULL, "password_hash" TEXT NOT NULL);
CREATE UNIQUE INDEX "admin_user_username" ON "admin_user" ("username");
CREATE TABLE "session" ("id" TEXT NOT NULL PRIMARY KEY, "admin_id" INTEGER NOT NULL, "csrf" TEXT NOT NULL, "expires_at" INTEGER NOT NULL, FOREIGN KEY ("admin_id") REFERENCES "admin_user" ("id"));
CREATE INDEX "session_admin_id" ON "session" ("admin_id");
CREATE TABLE "login_attempt" ("id" TEXT NOT NULL PRIMARY KEY, "count" INTEGER NOT NULL, "window_start" INTEGER NOT NULL);
CREATE TABLE "pixiv_account" ("id" INTEGER NOT NULL PRIMARY KEY, "pixiv_id" TEXT, "status" TEXT NOT NULL, "validated_at" INTEGER);
CREATE UNIQUE INDEX "pixiv_account_pixiv_id" ON "pixiv_account" ("pixiv_id");
CREATE TABLE "credential" ("account_id" INTEGER NOT NULL PRIMARY KEY, "ciphertext" TEXT NOT NULL, FOREIGN KEY ("account_id") REFERENCES "pixiv_account" ("id"));
CREATE TABLE "artist" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "alias" TEXT NOT NULL);
CREATE TABLE "artist_name" ("id" INTEGER NOT NULL PRIMARY KEY, "artist_id" TEXT NOT NULL, "name" TEXT NOT NULL, FOREIGN KEY ("artist_id") REFERENCES "artist" ("id"));
CREATE INDEX "artist_name_artist_id" ON "artist_name" ("artist_id");
CREATE UNIQUE INDEX "artist_name_artist_id_name" ON "artist_name" ("artist_id", "name");
CREATE TABLE "artwork" ("id" TEXT NOT NULL PRIMARY KEY, "artist_id" TEXT NOT NULL, "artist_name_at_collection" TEXT NOT NULL, "title" TEXT NOT NULL, "caption" TEXT NOT NULL, "kind" TEXT NOT NULL, "rating" TEXT NOT NULL, "page_count" INTEGER NOT NULL, "created_at" TEXT, "collected_at" INTEGER NOT NULL, "archive_status" TEXT NOT NULL, "remote_status" TEXT NOT NULL, "note" TEXT NOT NULL, "is_fixture" INTEGER NOT NULL, FOREIGN KEY ("artist_id") REFERENCES "artist" ("id"));
CREATE INDEX "artwork_artist_id" ON "artwork" ("artist_id");
CREATE TABLE "artwork_snapshot" ("id" INTEGER NOT NULL PRIMARY KEY, "artwork_id" TEXT NOT NULL, "revision" TEXT NOT NULL, "metadata" TEXT NOT NULL, "fetched_at" INTEGER NOT NULL, FOREIGN KEY ("artwork_id") REFERENCES "artwork" ("id"));
CREATE INDEX "artwork_snapshot_artwork_id" ON "artwork_snapshot" ("artwork_id");
CREATE UNIQUE INDEX "artwork_snapshot_artwork_id_revision" ON "artwork_snapshot" ("artwork_id", "revision");
CREATE TABLE "bookmark" ("id" INTEGER NOT NULL PRIMARY KEY, "account_id" INTEGER NOT NULL, "artwork_id" TEXT NOT NULL, "visibility" TEXT NOT NULL, "bookmarked_at" TEXT, "first_seen" INTEGER NOT NULL, "last_seen" INTEGER NOT NULL, "generation" TEXT, "status" TEXT NOT NULL, FOREIGN KEY ("account_id") REFERENCES "pixiv_account" ("id"), FOREIGN KEY ("artwork_id") REFERENCES "artwork" ("id"));
CREATE INDEX "bookmark_account_id" ON "bookmark" ("account_id");
CREATE INDEX "bookmark_artwork_id" ON "bookmark" ("artwork_id");
CREATE UNIQUE INDEX "bookmark_account_id_artwork_id" ON "bookmark" ("account_id", "artwork_id");
CREATE TABLE "tag" ("id" INTEGER NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "search_key" TEXT NOT NULL);
CREATE UNIQUE INDEX "tag_name" ON "tag" ("name");
CREATE INDEX "tag_search_key" ON "tag" ("search_key");
CREATE TABLE "tag_translation" ("id" INTEGER NOT NULL PRIMARY KEY, "tag_id" INTEGER NOT NULL, "language" TEXT NOT NULL, "name" TEXT NOT NULL, "source" TEXT NOT NULL, FOREIGN KEY ("tag_id") REFERENCES "tag" ("id"));
CREATE INDEX "tag_translation_tag_id" ON "tag_translation" ("tag_id");
CREATE UNIQUE INDEX "tag_translation_tag_id_language_source" ON "tag_translation" ("tag_id", "language", "source");
CREATE TABLE "artwork_tag" ("id" INTEGER NOT NULL PRIMARY KEY, "artwork_id" TEXT NOT NULL, "tag_id" INTEGER NOT NULL, "source" TEXT NOT NULL, FOREIGN KEY ("artwork_id") REFERENCES "artwork" ("id"), FOREIGN KEY ("tag_id") REFERENCES "tag" ("id"));
CREATE INDEX "artwork_tag_artwork_id" ON "artwork_tag" ("artwork_id");
CREATE INDEX "artwork_tag_tag_id" ON "artwork_tag" ("tag_id");
CREATE UNIQUE INDEX "artwork_tag_artwork_id_tag_id_source" ON "artwork_tag" ("artwork_id", "tag_id", "source");
CREATE TABLE "bookmark_tag" ("id" INTEGER NOT NULL PRIMARY KEY, "bookmark_id" INTEGER NOT NULL, "tag_id" INTEGER NOT NULL, FOREIGN KEY ("bookmark_id") REFERENCES "bookmark" ("id"), FOREIGN KEY ("tag_id") REFERENCES "tag" ("id"));
CREATE INDEX "bookmark_tag_bookmark_id" ON "bookmark_tag" ("bookmark_id");
CREATE INDEX "bookmark_tag_tag_id" ON "bookmark_tag" ("tag_id");
CREATE UNIQUE INDEX "bookmark_tag_bookmark_id_tag_id" ON "bookmark_tag" ("bookmark_id", "tag_id");
CREATE TABLE "asset" ("id" TEXT NOT NULL PRIMARY KEY, "artwork_id" TEXT NOT NULL, "revision" TEXT NOT NULL, "page" INTEGER NOT NULL, "role" TEXT NOT NULL, "path" TEXT NOT NULL, "sha256" TEXT NOT NULL, "size" INTEGER NOT NULL, "width" INTEGER NOT NULL, "height" INTEGER NOT NULL, "media_type" TEXT NOT NULL, "state" TEXT NOT NULL, FOREIGN KEY ("artwork_id") REFERENCES "artwork" ("id"));
CREATE INDEX "asset_artwork_id" ON "asset" ("artwork_id");
CREATE UNIQUE INDEX "asset_path" ON "asset" ("path");
CREATE UNIQUE INDEX "asset_artwork_id_revision_page_role" ON "asset" ("artwork_id", "revision", "page", "role");
CREATE TABLE "sync_run" ("id" INTEGER NOT NULL PRIMARY KEY, "account_id" INTEGER NOT NULL, "scope" TEXT NOT NULL, "generation" TEXT NOT NULL, "cursor" TEXT, "state" TEXT NOT NULL, FOREIGN KEY ("account_id") REFERENCES "pixiv_account" ("id"));
CREATE INDEX "sync_run_account_id" ON "sync_run" ("account_id");
CREATE TABLE "job" ("id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL, "state" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "active_key" TEXT, "lease_key" TEXT NOT NULL, "owner" TEXT, "heartbeat" INTEGER, "lease_until" INTEGER, "processed" INTEGER NOT NULL, "total" INTEGER, "failed" INTEGER NOT NULL, "error_code" TEXT, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE INDEX "job_state" ON "job" ("state");
CREATE UNIQUE INDEX "job_idempotency_key" ON "job" ("idempotency_key");
CREATE UNIQUE INDEX "job_active_key" ON "job" ("active_key");
CREATE TABLE "job_event" ("id" INTEGER NOT NULL PRIMARY KEY, "job_id" TEXT NOT NULL, "state" TEXT NOT NULL, "code" TEXT, "created_at" INTEGER NOT NULL, FOREIGN KEY ("job_id") REFERENCES "job" ("id"));
CREATE INDEX "job_event_job_id" ON "job_event" ("job_id");
CREATE TABLE "outbox" ("id" INTEGER NOT NULL PRIMARY KEY, "job_id" TEXT NOT NULL, "delivered_at" INTEGER, "attempts" INTEGER NOT NULL, FOREIGN KEY ("job_id") REFERENCES "job" ("id"));
CREATE UNIQUE INDEX "outbox_job_id" ON "outbox" ("job_id");
CREATE TABLE "lease" ("key" TEXT NOT NULL PRIMARY KEY, "owner" TEXT NOT NULL, "expires_at" INTEGER NOT NULL);
CREATE TABLE "tombstone" ("artwork_id" TEXT NOT NULL PRIMARY KEY, "created_at" INTEGER NOT NULL);
CREATE TABLE "setting" ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NOT NULL);
